-- kontrola listů skupiny t (generováno z finálních souborů) – jen test
CREATE TEMP TABLE t_exp(f text, tbl text, k text, sub text, how text, old text, new text);
INSERT INTO t_exp VALUES
($q$20261112t01$q$,$q$cms_variables$q$,$q$web.jak_pujcit_dokumenty.payments.rows.2.1$q$,$q$cs$q$,$q$full$q$,$q$3997e98e83eb05f3ac0b1ed601a303ea$q$,$q$Vrácení bez povinnosti tankovat – jen ať nesvítí rezerva. Umytou je potřeba motorku vrátit jen na samoobslužné pobočce ve Velkých Němčicích. Případné nadměrné znečištění řešíme individuálně.$q$),
($q$20261112t01$q$,$q$cms_variables$q$,$q$web.jak_pujcit_dokumenty.payments.rows.2.1$q$,$q$de$q$,$q$full$q$,$q$5a60659e5346ed9d5ed523adde50b539$q$,$q$Rückgabe ohne Tankpflicht – nur die Reserveleuchte sollte nicht leuchten. Gewaschen zurückgeben musst du das Motorrad nur an der Selbstbedienungsfiliale in Velké Němčice. Starke Verschmutzung klären wir individuell.$q$),
($q$20261112t01$q$,$q$cms_variables$q$,$q$web.jak_pujcit_dokumenty.payments.rows.2.1$q$,$q$en$q$,$q$full$q$,$q$ef68b07aa209417b7c63e82e2a55af53$q$,$q$Return without having to refuel – just make sure the reserve light isn't on. The bike only needs to be returned washed at the self-service branch in Velké Němčice. Excessive dirt is dealt with individually.$q$),
($q$20261112t01$q$,$q$cms_variables$q$,$q$web.jak_pujcit_dokumenty.payments.rows.2.1$q$,$q$es$q$,$q$full$q$,$q$eff2d339901af941997a66917266ecc2$q$,$q$Devolución sin obligación de repostar; solo procura que no esté encendido el testigo de reserva. Solo hay que devolver la moto lavada en la sucursal de autoservicio de Velké Němčice. La suciedad excesiva se resuelve de forma individual.$q$),
($q$20261112t01$q$,$q$cms_variables$q$,$q$web.jak_pujcit_dokumenty.payments.rows.2.1$q$,$q$fr$q$,$q$full$q$,$q$d8cef6b75d78afaa4067831c81c528fe$q$,$q$Restitution sans obligation de faire le plein – veille seulement à ce que le voyant de réserve ne soit pas allumé. La moto ne doit être rendue lavée qu'à l'agence en libre-service de Velké Němčice. Une saleté excessive est réglée au cas par cas.$q$),
($q$20261112t01$q$,$q$cms_variables$q$,$q$web.jak_pujcit_dokumenty.payments.rows.2.1$q$,$q$nl$q$,$q$full$q$,$q$81283cc171b4fd6b516a481714b97c08$q$,$q$Terugbrengen zonder tankplicht – zorg alleen dat het reservelampje niet brandt. Alleen bij de zelfbedieningsvestiging in Velké Němčice moet de motor gewassen worden ingeleverd. Overmatig vuil wordt individueel afgehandeld.$q$),
($q$20261112t01$q$,$q$cms_variables$q$,$q$web.jak_pujcit_dokumenty.payments.rows.2.1$q$,$q$pl$q$,$q$full$q$,$q$7f6306087eba80116a95a1ee1532baab$q$,$q$Zwrot bez obowiązku tankowania – byle nie świeciła się kontrolka rezerwy. Umyty motocykl trzeba oddać tylko w samoobsługowym oddziale Velké Němčice. Nadmierne zabrudzenie rozpatrujemy indywidualnie.$q$),
($q$20261112t01$q$,$q$cms_variables$q$,$q$web.jak_pujcit_postup.process.steps.11.text$q$,$q$cs$q$,$q$full$q$,$q$fddf262875df0f985f55357e38d23e65$q$,$q$Motorku vrať včas – osobně na pobočku, kde sis ji půjčil (Mezná u Pelhřimova, nebo samoobslužné Velké Němčice u Brna), u motorek z Mezné i na předem sjednané místo. Tankovat nemusíš – jen ať nesvítí rezerva. Umytou ji vracej jen na samoobslužné pobočce ve Velkých Němčicích.$q$),
($q$20261112t01$q$,$q$cms_variables$q$,$q$web.jak_pujcit_postup.process.steps.11.text$q$,$q$de$q$,$q$full$q$,$q$b2eff727660dfd22e19b413e7dbe19ec$q$,$q$Bring das Motorrad pünktlich zurück – persönlich in die Filiale, in der du es gemietet hast (Mezná bei Pelhřimov oder die Selbstbedienungsfiliale in Velké Němčice bei Brno), Motorräder aus Mezná auch an einen vorher vereinbarten Ort. Tanken musst du nicht – nur die Reserveleuchte sollte nicht leuchten. Gewaschen zurückbringen musst du es nur an der Selbstbedienungsfiliale in Velké Němčice.$q$),
($q$20261112t01$q$,$q$cms_variables$q$,$q$web.jak_pujcit_postup.process.steps.11.text$q$,$q$en$q$,$q$full$q$,$q$00f47e67c49d35a91f231547e9bc80e5$q$,$q$Return the bike on time – in person at the branch you rented it from (Mezná near Pelhřimov or the self-service branch in Velké Němčice near Brno), or, for bikes from Mezná, at a place agreed in advance. No need to refuel – just make sure the reserve light isn't on. It only needs to be returned washed at the self-service branch in Velké Němčice.$q$),
($q$20261112t01$q$,$q$cms_variables$q$,$q$web.jak_pujcit_postup.process.steps.11.text$q$,$q$es$q$,$q$full$q$,$q$5e9b8ae1cbeff282a91afcdd67362644$q$,$q$Devuelve la moto a tiempo: en persona en la sucursal donde la alquilaste (Mezná, cerca de Pelhřimov, o el autoservicio de Velké Němčice, cerca de Brno) o, si es de Mezná, también en el lugar acordado previamente. No tienes que repostar; solo procura que no esté encendido el testigo de reserva. Solo en la sucursal de autoservicio de Velké Němčice hay que devolverla lavada.$q$),
($q$20261112t01$q$,$q$cms_variables$q$,$q$web.jak_pujcit_postup.process.steps.11.text$q$,$q$fr$q$,$q$full$q$,$q$4068e84bf4244c7095d6f76397023e6a$q$,$q$Rends la moto à l'heure – en personne à l'agence où tu l'as louée (Mezná, près de Pelhřimov, ou l'agence en libre-service de Velké Němčice, près de Brno) ou, pour les motos de Mezná, à un endroit convenu à l'avance. Pas besoin de faire le plein – veille seulement à ce que le voyant de réserve ne soit pas allumé. Tu ne dois la rendre lavée qu'à l'agence en libre-service de Velké Němčice.$q$),
($q$20261112t01$q$,$q$cms_variables$q$,$q$web.jak_pujcit_postup.process.steps.11.text$q$,$q$nl$q$,$q$full$q$,$q$3bf31f957632989cb6951e1f7502d25f$q$,$q$Breng de motor op tijd terug – persoonlijk naar de vestiging waar je hem huurde (Mezná bij Pelhřimov of de zelfbedieningsvestiging in Velké Němčice bij Brno), motoren uit Mezná ook op de afgesproken plek. Tanken is niet nodig – zorg alleen dat het reservelampje niet brandt. Alleen bij de zelfbedieningsvestiging in Velké Němčice lever je hem gewassen in.$q$),
($q$20261112t01$q$,$q$cms_variables$q$,$q$web.jak_pujcit_postup.process.steps.11.text$q$,$q$pl$q$,$q$full$q$,$q$ed3830fbdf8ff626af2bfc8a473b0d0b$q$,$q$Zwróć motocykl na czas – osobiście w oddziale, w którym go wypożyczyłeś (Mezná koło Pelhřimova albo samoobsługowy oddział Velké Němčice koło Brna), a motocykle z oddziału Mezná także w umówionym miejscu. Tankować nie musisz – byle nie świeciła się kontrolka rezerwy. Umyty motocykl oddajesz tylko w samoobsługowym oddziale Velké Němčice.$q$),
($q$20261112t01$q$,$q$cms_variables$q$,$q$web.jak_pujcit_postup.process.steps.11.text$q$,$q$uk$q$,$q$full$q$,$q$79b14ea890e45fd521302692080789a8$q$,$q$Поверни мотоцикл вчасно – особисто у філію, де ти його взяв (Mezná біля Пельгржимова або філія самообслуговування Velké Němčice біля Брна), а мотоцикли з Mezná й у заздалегідь узгоджене місце. Заправляти не потрібно – лише стеж, щоб не світився індикатор резерву. Вимитим повертай його лише у філії самообслуговування Velké Němčice.$q$),
($q$20261112t01$q$,$q$cms_variables$q$,$q$web.jak_pujcit_vraceni_pujcovna.intro$q$,$q$cs$q$,$q$full$q$,$q$e209cf8cac0dcb94a66b8eac1750455b$q$,$q$Výpůjčka končí stejně jednoduše jako začala. Přijeď v domluvený čas vrácení na naši adresu v Mezné u Pelhřimova. Vrať motorku a zapůjčenou výbavu a je hotovo. Před vrácením nemusíš mýt ani tankovat – jen ať nesvítí rezerva.&nbsp;$q$),
($q$20261112t01$q$,$q$cms_variables$q$,$q$web.jak_pujcit_vraceni_pujcovna.intro$q$,$q$de$q$,$q$full$q$,$q$95d3e312ba728d070e7328efe4a21549$q$,$q$Deine Miete endet genauso einfach, wie sie begonnen hat. Komm zur vereinbarten Rückgabezeit an unsere Adresse in Mezná bei Pelhřimov. Gib das Motorrad und die geliehene Ausrüstung zurück – fertig. Vor der Rückgabe musst du es weder waschen noch tanken – nur die Reserveleuchte sollte nicht leuchten.&nbsp;$q$),
($q$20261112t01$q$,$q$cms_variables$q$,$q$web.jak_pujcit_vraceni_pujcovna.intro$q$,$q$en$q$,$q$full$q$,$q$6ed81514f481d59036b1e58f3a30b72a$q$,$q$Your rental ends just as easily as it began. Come to our address in Mezná near Pelhřimov at the agreed return time. Return the bike and the rented gear and you're done. Before returning, you don't need to wash or refuel it – just make sure the reserve light isn't on.&nbsp;$q$),
($q$20261112t01$q$,$q$cms_variables$q$,$q$web.jak_pujcit_vraceni_pujcovna.intro$q$,$q$es$q$,$q$full$q$,$q$b4aa8bcb050e39dc0e37c216f78e61c3$q$,$q$El alquiler termina tan fácil como empezó. Ven a la hora de devolución acordada a nuestra dirección en Mezná, cerca de Pelhřimov. Devuelve la moto y el equipamiento alquilado, y listo. Antes de devolverla no tienes que lavarla ni repostar; solo procura que no esté encendido el testigo de reserva.&nbsp;$q$),
($q$20261112t02$q$,$q$cms_variables$q$,$q$web.jak_pujcit_vraceni_pujcovna.intro$q$,$q$fr$q$,$q$full$q$,$q$87f465846fe7754e0fba393996747b9d$q$,$q$Ta location se termine aussi simplement qu'elle a commencé. Viens à l'heure de restitution convenue à notre adresse à Mezná, près de Pelhřimov. Rends la moto et l'équipement loué – et c'est terminé. Avant la restitution, pas besoin de laver la moto ni de faire le plein – veille seulement à ce que le voyant de réserve ne soit pas allumé.&nbsp;$q$),
($q$20261112t02$q$,$q$cms_variables$q$,$q$web.jak_pujcit_vraceni_pujcovna.intro$q$,$q$nl$q$,$q$full$q$,$q$0194bce6a4daa125e1716c735a96f4a6$q$,$q$Je huur eindigt net zo eenvoudig als hij begon. Kom op de afgesproken inlevertijd naar ons adres in Mezná bij Pelhřimov. Lever de motor en de gehuurde uitrusting in en klaar. Voor het inleveren hoef je de motor niet te wassen of te tanken – zorg alleen dat het reservelampje niet brandt.&nbsp;$q$),
($q$20261112t02$q$,$q$cms_variables$q$,$q$web.jak_pujcit_vraceni_pujcovna.intro$q$,$q$pl$q$,$q$full$q$,$q$ea4ab4e5560780e7c40961e9ebc965dd$q$,$q$Wypożyczenie kończy się tak samo prosto, jak się zaczęło. Przyjedź o umówionej godzinie zwrotu pod nasz adres w Mezná koło Pelhřimova. Oddaj motocykl i wypożyczony sprzęt – i gotowe. Przed zwrotem nie musisz go myć ani tankować – byle nie świeciła się kontrolka rezerwy.&nbsp;$q$),
($q$20261112t02$q$,$q$cms_variables$q$,$q$web.jak_pujcit_vraceni_pujcovna.intro$q$,$q$uk$q$,$q$full$q$,$q$c77e4212409cb9b9ac569e4a071b0e67$q$,$q$Оренда закінчується так само просто, як і почалася. Приїдь у домовлений час повернення за нашою адресою в Mezná біля Пельгржимова. Поверни мотоцикл та орендоване екіпірування – і готово. Перед поверненням мити чи заправляти його не потрібно – лише стеж, щоб не світився індикатор резерву.&nbsp;$q$),
($q$20261112t02$q$,$q$cms_variables$q$,$q$web.jak_pujcit_vraceni_pujcovna.cta.text$q$,$q$cs$q$,$q$full$q$,$q$07906eb8c2a7181c6a3a038e0134611a$q$,$q$MotoGo24 je půjčovna motorek na Vysočině s nonstop provozem a jednoduchým vrácením motorky kdykoliv v den výpůjčky. Bez kauce, bez tankování (jen ať nesvítí rezerva), v Mezné i bez mytí. Vyber si z naší široké nabídky motorek (a skútrů) a rezervuj online z pohodlí domova.$q$),
($q$20261112t02$q$,$q$cms_variables$q$,$q$web.jak_pujcit_vraceni_pujcovna.cta.text$q$,$q$de$q$,$q$full$q$,$q$1389cfd4d346edc59c21ae767993b046$q$,$q$MotoGo24 ist ein Motorradverleih in der Region Vysočina mit Nonstop-Betrieb und einfacher Rückgabe jederzeit an deinem Miettag. Keine Kaution, kein Tanken (nur die Reserveleuchte sollte nicht leuchten) und in Mezná auch kein Waschen. Wähle aus unserem großen Angebot an Motorrädern (und Rollern) und buche bequem online von zu Hause aus.$q$),
($q$20261112t02$q$,$q$cms_variables$q$,$q$web.jak_pujcit_vraceni_pujcovna.cta.text$q$,$q$en$q$,$q$full$q$,$q$ef2831097fbe80ff91c53247584c03b4$q$,$q$MotoGo24 is a motorcycle rental in the Vysočina region that runs 24/7, with an easy return any time on your rental day. No deposit, no refuelling (just make sure the reserve light isn't on) and, in Mezná, no washing either. Choose from our wide range of motorcycles (and scooters) and book online from the comfort of your home.$q$),
($q$20261112t02$q$,$q$cms_variables$q$,$q$web.jak_pujcit_vraceni_pujcovna.cta.text$q$,$q$es$q$,$q$full$q$,$q$736f0aa8ee4f9dd6169bd195640f54e4$q$,$q$MotoGo24 es un alquiler de motos en la región de Vysočina que funciona 24/7, con una devolución sencilla en cualquier momento del día del alquiler. Sin fianza, sin repostar (solo procura que no esté encendido el testigo de reserva) y, en Mezná, también sin lavar. Elige entre nuestra amplia oferta de motos (y scooters) y reserva online desde la comodidad de tu casa.$q$),
($q$20261112t02$q$,$q$cms_variables$q$,$q$web.jak_pujcit_vraceni_pujcovna.cta.text$q$,$q$fr$q$,$q$full$q$,$q$66f1041e94de7cd3cc8c37a974345f3f$q$,$q$MotoGo24 est une location de motos dans la région de Vysočina qui fonctionne 24h/24, avec une restitution simple à toute heure le jour de ta location. Pas de caution, pas de plein à faire (veille seulement à ce que le voyant de réserve ne soit pas allumé) et, à Mezná, pas de lavage non plus. Choisis parmi notre large gamme de motos (et de scooters) et réserve en ligne depuis chez toi.$q$),
($q$20261112t02$q$,$q$cms_variables$q$,$q$web.jak_pujcit_vraceni_pujcovna.cta.text$q$,$q$nl$q$,$q$full$q$,$q$a62f7b2dc12896c1d2cdf6104339bf50$q$,$q$MotoGo24 is een motorverhuur in de regio Vysočina die 24/7 werkt, met eenvoudig inleveren op elk moment van je huurdag. Geen borg, niet tanken (zorg alleen dat het reservelampje niet brandt) en in Mezná ook niet wassen. Kies uit ons ruime aanbod aan motoren (en scooters) en reserveer online vanuit je luie stoel.$q$),
($q$20261112t02$q$,$q$cms_variables$q$,$q$web.jak_pujcit_vraceni_pujcovna.cta.text$q$,$q$pl$q$,$q$full$q$,$q$9b2ff5e2fb8bb013bac44deaf0e3db5c$q$,$q$MotoGo24 to wypożyczalnia motocykli w regionie Vysočina działająca całodobowo, z prostym zwrotem o dowolnej porze w dniu wynajmu. Bez kaucji, bez tankowania (byle nie świeciła się kontrolka rezerwy), a w oddziale Mezná także bez mycia. Wybierz z naszej szerokiej oferty motocykli (i skuterów) i zarezerwuj online w zaciszu domu.$q$),
($q$20261112t02$q$,$q$cms_variables$q$,$q$web.jak_pujcit_vraceni_pujcovna.cta.text$q$,$q$uk$q$,$q$full$q$,$q$6cd62288582c518facabe1a0524f6815$q$,$q$MotoGo24 – це прокат мотоциклів на Височині з цілодобовою роботою та простим поверненням мотоцикла будь-коли в день оренди. Без застави, без заправки (лише щоб не світився індикатор резерву), а в Mezná ще й без миття. Обирай із нашої широкої пропозиції мотоциклів (і скутерів) та бронюй онлайн, не виходячи з дому.$q$),
($q$20261112t03$q$,$q$cms_variables$q$,$q$web.jak_pujcit_dokumenty.handover.items.0$q$,$q$cs$q$,$q$full$q$,$q$f005050f8900a494b6d68c09ad69dc86$q$,$q$<strong>Převzetí</strong>&nbsp;probíhá v Pelhřimově (Mezná 9) nebo na samoobslužné pobočce ve Velkých Němčicích u Brna; z Mezné je možné i&nbsp;<a href="/jak-pujcit/pristaveni">přistavení</a>.$q$),
($q$20261112t03$q$,$q$cms_variables$q$,$q$web.jak_pujcit_dokumenty.handover.items.0$q$,$q$de$q$,$q$full$q$,$q$b55191c87fd912ef0f4c862a5922ceb9$q$,$q$Die <strong>Abholung</strong>&nbsp;ist in Pelhřimov (Mezná 9) oder an der Selbstbedienungsfiliale in Velké Němčice bei Brno – von Mezná aus kannst du auch unsere&nbsp;<a href="/jak-pujcit/pristaveni">Lieferung</a> nutzen.$q$),
($q$20261112t03$q$,$q$cms_variables$q$,$q$web.jak_pujcit_dokumenty.handover.items.0$q$,$q$en$q$,$q$full$q$,$q$777b090de276ce5d8e1169bd0f9c1dfe$q$,$q$<strong>Pick-up</strong>&nbsp;is in Pelhřimov (Mezná 9) or at the self-service branch in Velké Němčice near Brno; from Mezná you can also use&nbsp;<a href="/jak-pujcit/pristaveni">delivery</a>.$q$),
($q$20261112t03$q$,$q$cms_variables$q$,$q$web.jak_pujcit_dokumenty.handover.items.0$q$,$q$es$q$,$q$full$q$,$q$e274d41584a634e82558a482ca3d3212$q$,$q$La&nbsp;<strong>recogida</strong>&nbsp;es en Pelhřimov (Mezná 9) o en la sucursal de autoservicio de Velké Němčice, cerca de Brno; desde Mezná también puedes pedir la&nbsp;<a href="/jak-pujcit/pristaveni">entrega de la moto</a>.$q$),
($q$20261112t03$q$,$q$cms_variables$q$,$q$web.jak_pujcit_dokumenty.handover.items.0$q$,$q$fr$q$,$q$full$q$,$q$68671f0eea19ec32b28146051025fdc9$q$,$q$La <strong>prise en charge</strong>&nbsp;se fait à Pelhřimov (Mezná 9) ou à l'agence en libre-service de Velké Němčice, près de Brno – depuis Mezná, profite aussi de notre&nbsp;<a href="/jak-pujcit/pristaveni">livraison</a>.$q$),
($q$20261112t03$q$,$q$cms_variables$q$,$q$web.jak_pujcit_dokumenty.handover.items.0$q$,$q$nl$q$,$q$full$q$,$q$ab6f286a0e35353eaab6fbcf00945bbc$q$,$q$Het&nbsp;<strong>ophalen</strong>&nbsp;gebeurt in Pelhřimov (Mezná 9) of bij de zelfbedieningsvestiging in Velké Němčice bij Brno; vanuit Mezná kun je ook&nbsp;<a href="/jak-pujcit/pristaveni">bezorging</a> gebruiken.$q$),
($q$20261112t03$q$,$q$cms_variables$q$,$q$web.jak_pujcit_dokumenty.handover.items.0$q$,$q$pl$q$,$q$full$q$,$q$22b98e829fd22de95a52de8ff08d93db$q$,$q$<strong>Odbiór</strong>&nbsp;odbywa się w Pelhřimovie (Mezná 9) lub w samoobsługowym oddziale Velké Němčice koło Brna; z oddziału Mezná możesz też skorzystać z&nbsp;<a href="/jak-pujcit/pristaveni">podstawienia</a>.$q$),
($q$20261112t03$q$,$q$cms_variables$q$,$q$web.jak_pujcit_postup.intro_p2$q$,$q$cs$q$,$q$full$q$,$q$a7f4d4cca8a0b2df87cb8dac04ffa09f$q$,$q$V naší <strong>motopůjčovně </strong>zvládneš vše online: vyber motorku, zvol termín a vyplň rezervační formulář – včetně výbavy a způsobu předání. Motorku si vyzvedni v Mezné u Pelhřimova (odtud ti ji můžeme i přistavit kamkoliv v ČR), nebo samoobslužně ve Velkých Němčicích u Brna. Platbu provedeš online při dokončení rezervace.$q$),
($q$20261112t03$q$,$q$cms_variables$q$,$q$web.jak_pujcit_postup.intro_p2$q$,$q$de$q$,$q$full$q$,$q$32acd14a68879e0af63e70dbb227ef95$q$,$q$In unserem <strong>Motorradverleih</strong> erledigst du alles online: Motorrad wählen, Termin festlegen und Buchungsformular ausfüllen – inklusive Ausrüstung und Art der Übergabe. Hol das Motorrad in Mezná bei Pelhřimov ab (von dort liefern wir es dir auch überallhin in Tschechien) oder per Selbstbedienung in Velké Němčice bei Brno. Bezahlt wird online beim Abschluss der Buchung.$q$),
($q$20261112t03$q$,$q$cms_variables$q$,$q$web.jak_pujcit_postup.intro_p2$q$,$q$en$q$,$q$full$q$,$q$31b9b72db851e8983e0000b909256c75$q$,$q$At our <strong>motorcycle rental</strong> you do everything online: choose a bike, pick your dates and fill in the booking form – including gear and how you want to receive the bike. Pick it up in Mezná near Pelhřimov (from there we can also deliver it anywhere in the Czech Republic) or at the self-service branch in Velké Němčice near Brno. You pay online when you complete your booking.$q$),
($q$20261112t03$q$,$q$cms_variables$q$,$q$web.jak_pujcit_postup.intro_p2$q$,$q$es$q$,$q$full$q$,$q$4c43cb93feb22d8737aae1b934920631$q$,$q$En nuestro <strong>alquiler de motos</strong> lo haces todo online: eliges la moto, escoges las fechas y rellenas el formulario de reserva, incluido el equipamiento y la forma de entrega. Recoge la moto en Mezná, cerca de Pelhřimov (desde allí también te la llevamos a cualquier lugar de la República Checa), o en el autoservicio de Velké Němčice, cerca de Brno. Pagas online al completar la reserva.$q$),
($q$20261112t03$q$,$q$cms_variables$q$,$q$web.jak_pujcit_postup.intro_p2$q$,$q$fr$q$,$q$full$q$,$q$eb6fbf7b156583819634faa986c92829$q$,$q$Dans notre <strong>location de motos</strong>, tu fais tout en ligne : tu choisis la moto, tu fixes tes dates et tu remplis le formulaire de réservation – équipement et mode de remise compris. Récupère la moto à Mezná, près de Pelhřimov (d'où nous pouvons aussi te la livrer n'importe où en Tchéquie), ou en libre-service à Velké Němčice, près de Brno. Tu paies en ligne en finalisant la réservation.$q$),
($q$20261112t03$q$,$q$cms_variables$q$,$q$web.jak_pujcit_postup.intro_p2$q$,$q$nl$q$,$q$full$q$,$q$01e8a06de5979ad10d51af57e7f3f2f1$q$,$q$Bij onze <strong>motorverhuur</strong> doe je alles online: kies een motor, kies een datum en vul het reserveringsformulier in – inclusief uitrusting en overdrachtsmethode. Haal de motor op in Mezná bij Pelhřimov (vanaf daar bezorgen we ook overal in Tsjechië) of via zelfbediening in Velké Němčice bij Brno. Je betaalt online bij het voltooien van de reservering.$q$),
($q$20261112t03$q$,$q$cms_variables$q$,$q$web.jak_pujcit_postup.intro_p2$q$,$q$pl$q$,$q$full$q$,$q$449bd5cf7bc76bca0bf94dd134e95a2f$q$,$q$W naszej <strong>wypożyczalni motocykli</strong> wszystko załatwisz online: wybierz motocykl, wybierz termin i wypełnij formularz rezerwacji – wraz z wyposażeniem i sposobem przekazania. Odbierz motocykl w oddziale Mezná koło Pelhřimova (stamtąd możemy go też podstawić w dowolne miejsce w Czechach) albo samoobsługowo w Velké Němčice koło Brna. Płacisz online przy finalizacji rezerwacji.$q$),
($q$20261112t03$q$,$q$cms_variables$q$,$q$web.jak_pujcit_postup.process.steps.4.text$q$,$q$cs$q$,$q$full$q$,$q$a89d691f3229e007eba118490a24d614$q$,$q$Vyber místo převzetí – osobně v Mezné u Pelhřimova, samoobslužně ve Velkých Němčicích u Brna, nebo přistavení z Mezné kamkoliv v ČR.&nbsp;$q$),
($q$20261112t03$q$,$q$cms_variables$q$,$q$web.jak_pujcit_postup.process.steps.4.text$q$,$q$de$q$,$q$full$q$,$q$f2134f282ebdc13ef488d8cbffc6efe1$q$,$q$Wähle, wie du das Motorrad bekommst – persönlich in Mezná bei Pelhřimov, per Selbstbedienung in Velké Němčice bei Brno oder per Lieferung ab Mezná überallhin in Tschechien.&nbsp;$q$),
($q$20261112t03$q$,$q$cms_variables$q$,$q$web.jak_pujcit_postup.process.steps.4.text$q$,$q$en$q$,$q$full$q$,$q$2e6a300b44846b98731f4c79da973959$q$,$q$Choose how you get the bike – in person in Mezná near Pelhřimov, self-service in Velké Němčice near Brno, or delivered from Mezná anywhere in the Czech Republic.&nbsp;$q$),
($q$20261112t03$q$,$q$cms_variables$q$,$q$web.jak_pujcit_postup.process.steps.4.text$q$,$q$es$q$,$q$full$q$,$q$914cca5b92c55a3a97315a1892568d8e$q$,$q$Elige dónde recibes la moto: en persona en nuestra sucursal de Mezná, cerca de Pelhřimov; en el autoservicio de Velké Němčice, cerca de Brno; o con entrega desde Mezná en cualquier lugar de la República Checa.&nbsp;$q$),
($q$20261112t03$q$,$q$cms_variables$q$,$q$web.jak_pujcit_postup.process.steps.4.text$q$,$q$fr$q$,$q$full$q$,$q$c822259258a6a43279c43d6315741ce4$q$,$q$Choisis comment tu récupères la moto – en personne à Mezná, près de Pelhřimov, en libre-service à Velké Němčice, près de Brno, ou par livraison depuis Mezná n'importe où en Tchéquie.&nbsp;$q$),
($q$20261112t03$q$,$q$cms_variables$q$,$q$web.jak_pujcit_postup.process.steps.4.text$q$,$q$nl$q$,$q$full$q$,$q$eb7a61e68f3493f40dd148c9adb4e6c3$q$,$q$Selecteer de ophaalmethode – persoonlijk in Mezná bij Pelhřimov, via zelfbediening in Velké Němčice bij Brno, of bezorging vanuit Mezná overal in Tsjechië.&nbsp;$q$),
($q$20261112t03$q$,$q$cms_variables$q$,$q$web.jak_pujcit_postup.process.steps.4.text$q$,$q$pl$q$,$q$full$q$,$q$8a2bb297485e83f7627cf6c9f44e039c$q$,$q$Wybierz sposób odbioru – osobiście w oddziale Mezná koło Pelhřimova, samoobsługowo w Velké Němčice koło Brna albo podstawienie z oddziału Mezná w dowolne miejsce w Czechach.&nbsp;$q$),
($q$20261112t03$q$,$q$cms_variables$q$,$q$web.jak_pujcit_postup.process.steps.4.text$q$,$q$uk$q$,$q$full$q$,$q$0d9040a9bd9b76d5d76cab337016b394$q$,$q$Вибери спосіб отримання – особисто в Mezná біля Пельгржимова, самостійно у філії самообслуговування Velké Němčice біля Брна або доставку з Mezná будь-куди в ЧР.&nbsp;$q$),
($q$20261112t04$q$,$q$cms_variables$q$,$q$web.jak_pujcit_vyzvednuti.intro$q$,$q$cs$q$,$q$full$q$,$q$8638a6e0175c2e0167a6d38f5e4de5c7$q$,$q$V <strong>Motogo24 – půjčovně motorek na Vysočině</strong>&nbsp;je převzetí motorky otázkou pár minut. Půjčujeme bez <strong>kauce, s výbavou pro řidiče v ceně a nonstop provozem</strong>. Přijď osobně do Mezné u Pelhřimova a vyraz na cestu! Na samoobslužné pobočce ve Velkých Němčicích u Brna si motorku vyzvedneš sám přístupovým kódem z aplikace nebo e-mailu.$q$),
($q$20261112t04$q$,$q$cms_variables$q$,$q$web.jak_pujcit_vyzvednuti.intro$q$,$q$de$q$,$q$full$q$,$q$ddff73fc8045c2cae52cedac54d67521$q$,$q$Bei <strong>MotoGo24 – Motorradverleih in der Region Vysočina</strong>&nbsp;dauert die Abholung nur wenige Minuten. Wir vermieten <strong>ohne Kaution, mit Fahrerausrüstung inklusive und mit Abholung und Rückgabe rund um die Uhr</strong>. Komm persönlich nach Mezná bei Pelhřimov und ab auf die Straße! In der Selbstbedienungsfiliale in Velké Němčice bei Brno holst du das Motorrad selbst mit einem Zugangscode aus der App oder der E-Mail ab.$q$),
($q$20261112t04$q$,$q$cms_variables$q$,$q$web.jak_pujcit_vyzvednuti.intro$q$,$q$en$q$,$q$full$q$,$q$14c12a79b7da7470f21f0ce933020261$q$,$q$At <strong>MotoGo24 – motorcycle rental in the Vysočina region</strong>,&nbsp;picking up a bike takes just a few minutes. We rent with <strong>no deposit, rider gear included and 24/7 pick-up and return</strong>. Come to Mezná near Pelhřimov in person and hit the road! At the self-service branch in Velké Němčice near Brno you pick up the bike yourself with an access code from the app or e-mail.$q$),
($q$20261112t04$q$,$q$cms_variables$q$,$q$web.jak_pujcit_vyzvednuti.intro$q$,$q$es$q$,$q$full$q$,$q$4a19c33423cdd7583c72c4b646d2217c$q$,$q$En <strong>MotoGo24 – alquiler de motos en la región de Vysočina</strong>,&nbsp;recoger la moto es cuestión de pocos minutos. Alquilamos <strong>sin fianza, con el equipamiento del piloto incluido y con recogida y devolución 24/7</strong>. ¡Ven en persona a Mezná, cerca de Pelhřimov, y sal a la carretera! En la sucursal de autoservicio de Velké Němčice, cerca de Brno, recoges la moto tú mismo con un código de acceso de la app o del e-mail.$q$),
($q$20261112t04$q$,$q$cms_variables$q$,$q$web.jak_pujcit_vyzvednuti.intro$q$,$q$fr$q$,$q$full$q$,$q$d033252bf5e0062e6369bba35fa377e2$q$,$q$Chez <strong>MotoGo24 – location de motos dans la région de Vysočina</strong>,&nbsp;la prise en charge de la moto ne prend que quelques minutes. Nous louons <strong>sans caution, avec l'équipement du pilote inclus, et le retrait comme le retour se font 24h/24</strong>. Viens nous voir à Mezná, près de Pelhřimov, et en route ! À l'agence en libre-service de Velké Němčice, près de Brno, tu récupères la moto toi-même avec un code d'accès reçu dans l'appli ou par e-mail.$q$),
($q$20261112t04$q$,$q$cms_variables$q$,$q$web.jak_pujcit_vyzvednuti.intro$q$,$q$nl$q$,$q$full$q$,$q$5ff19c2ecdbd323ee54c8ca6c88aa27d$q$,$q$Bij <strong>MotoGo24 – motorverhuur in de regio Vysočina</strong> is het ophalen van de motor in een paar minuten geregeld. We verhuren <strong>zonder borg, met rijuitrusting inbegrepen en met ophalen en inleveren 24/7</strong>. Kom persoonlijk naar Mezná bij Pelhřimov en ga op pad! Bij de zelfbedieningsvestiging in Velké Němčice bij Brno haal je de motor zelf op met een toegangscode uit de app of de e-mail.$q$),
($q$20261112t04$q$,$q$cms_variables$q$,$q$web.jak_pujcit_vyzvednuti.intro$q$,$q$pl$q$,$q$full$q$,$q$b4a4e2ad2619f156e1a4f90da21285c1$q$,$q$W <strong>MotoGo24 – wypożyczalni motocykli w regionie Vysočina</strong> odbiór motocykla to kwestia kilku minut. Wypożyczamy <strong>bez kaucji, z wyposażeniem kierowcy w cenie oraz z odbiorem i zwrotem 24/7</strong>. Przyjedź osobiście do oddziału w Mezná koło Pelhřimova i ruszaj w drogę! W samoobsługowym oddziale Velké Němčice koło Brna odbierzesz motocykl sam za pomocą kodu dostępu z aplikacji lub e-maila.$q$),
($q$20261112t04$q$,$q$cms_variables$q$,$q$web.jak_pujcit_pristaveni.intro$q$,$q$cs$q$,$q$full$q$,$q$3df5738779e27d02e8ea5878592fec97$q$,$q$Chceš vyrazit bez zbytečného přesunu do půjčovny? Zajistíme <strong>přistavení motorky na domluvené místo</strong> – domů, do hotelu, k nádraží nebo na start tvého výletu. Motorku přivezeme kamkoliv v České republice – přímo z naší provozovny v Mezné u Pelhřimova. Přistavení nabízíme u motorek z obslužné pobočky v Mezné; motorky ze samoobslužné pobočky ve Velkých Němčicích se přebírají jen přímo na pobočce.$q$),
($q$20261112t04$q$,$q$cms_variables$q$,$q$web.jak_pujcit_pristaveni.intro$q$,$q$de$q$,$q$full$q$,$q$64c2c7061a7cd69f2b3c0e2e2c2bc520$q$,$q$Du willst losfahren, ohne erst zum Verleih zu fahren? Wir organisieren die <strong>Lieferung des Motorrads an einen vereinbarten Ort</strong> – nach Hause, ins Hotel, zum Bahnhof oder an den Start deiner Tour. Wir liefern überallhin in Tschechien – direkt aus unserer Filiale in Mezná bei Pelhřimov. Die Lieferung gibt es für Motorräder aus unserer Filiale mit Personal in Mezná; Motorräder der Selbstbedienungsfiliale in Velké Němčice holst du nur direkt dort ab.$q$),
($q$20261112t04$q$,$q$cms_variables$q$,$q$web.jak_pujcit_pristaveni.intro$q$,$q$en$q$,$q$full$q$,$q$7e4dd24e7acc6ad1f350a3adda291f57$q$,$q$Want to set off without travelling to the rental first? We'll arrange <strong>delivery of the bike to an agreed place</strong> – your home, a hotel, a train station or the start of your trip. We deliver anywhere in the Czech Republic – straight from our branch in Mezná near Pelhřimov. Delivery is available for bikes from our staffed branch in Mezná; bikes from the self-service branch in Velké Němčice are picked up only at that branch.$q$),
($q$20261112t04$q$,$q$cms_variables$q$,$q$web.jak_pujcit_pristaveni.intro$q$,$q$es$q$,$q$full$q$,$q$5e349189fc6977cdb7006f1200f6568e$q$,$q$¿Quieres salir sin tener que desplazarte hasta el alquiler? Te <strong>llevamos la moto al lugar acordado</strong>: a casa, al hotel, a la estación o al punto de salida de tu excursión. Te la llevamos a cualquier lugar de la República Checa, directamente desde nuestra sucursal de Mezná, cerca de Pelhřimov. La entrega está disponible para las motos de nuestra sucursal con personal de Mezná; las motos de la sucursal de autoservicio de Velké Němčice solo se recogen en esa sucursal.$q$),
($q$20261112t04$q$,$q$cms_variables$q$,$q$web.jak_pujcit_pristaveni.intro$q$,$q$fr$q$,$q$full$q$,$q$b6547176030404f9b624199edfdee0dd$q$,$q$Tu veux partir sans passer d'abord par l'agence ? Nous organisons la <strong>livraison de la moto à l'endroit convenu</strong> – chez toi, à l'hôtel, à la gare ou au point de départ de ta balade. Nous livrons partout en Tchéquie – directement depuis notre agence de Mezná, près de Pelhřimov. La livraison est proposée pour les motos de notre agence avec personnel de Mezná ; les motos de l'agence en libre-service de Velké Němčice se récupèrent uniquement sur place.$q$),
($q$20261112t04$q$,$q$cms_variables$q$,$q$web.jak_pujcit_pristaveni.intro$q$,$q$nl$q$,$q$full$q$,$q$97d24cec95db2712de9e49173258c992$q$,$q$Wil je vertrekken zonder eerst naar de verhuur te gaan? We zorgen voor <strong>bezorging van de motor op een afgesproken plek</strong> – thuis, bij je hotel, op het station of bij het startpunt van je tocht. We bezorgen overal in Tsjechië – rechtstreeks vanuit onze vestiging in Mezná bij Pelhřimov. Bezorging is mogelijk voor motoren van onze bemande vestiging in Mezná; motoren van de zelfbedieningsvestiging in Velké Němčice haal je alleen daar op.$q$),
($q$20261112t04$q$,$q$cms_variables$q$,$q$web.jak_pujcit_pristaveni.intro$q$,$q$pl$q$,$q$full$q$,$q$8c3368b639c3eb6a10bb4e7fb4b016df$q$,$q$Chcesz wyruszyć bez jazdy do wypożyczalni? Zorganizujemy <strong>dostawę motocykla w umówione miejsce</strong> – do domu, do hotelu, na dworzec albo na start twojej wycieczki. Dowieziemy go w dowolne miejsce w Czechach – prosto z naszego oddziału w Mezná koło Pelhřimova. Dostawę oferujemy dla motocykli z oddziału z obsługą w Mezná; motocykle z samoobsługowego oddziału Velké Němčice odbiera się tylko bezpośrednio w tym oddziale.$q$),
($q$20261112t05$q$,$q$cms_variables$q$,$q$web.jak_pujcit_pristaveni.intro$q$,$q$uk$q$,$q$full$q$,$q$0570bbbf166ab3d357defdef07753675$q$,$q$Хочеш вирушити без зайвих поїздок до прокату? Забезпечимо <strong>доставку мотоцикла у домовлене місце</strong> – додому, до готелю, до вокзалу чи на старт твоєї подорожі. Мотоцикл привеземо будь-куди в Чеській Республіці – прямо з нашої філії в Mezná біля Пельгржимова. Доставка можлива для мотоциклів із філії з персоналом у Mezná; мотоцикли з філії самообслуговування Velké Němčice можна забрати лише безпосередньо в цій філії.$q$),
($q$20261112t06$q$,$q$cms_variables$q$,$q$web.home.process.steps.2.text$q$,$q$cs$q$,$q$full$q$,$q$1beea6434848bcc3277b5861fff99650$q$,$q$Převezmi si motorku osobně v Mezné u Pelhřimova (odtud ti ji můžeme i přistavit kamkoli v ČR), nebo si ji vyzvedni sám na samoobslužné pobočce ve Velkých Němčicích u Brna.$q$),
($q$20261112t06$q$,$q$cms_variables$q$,$q$web.home.process.steps.2.text$q$,$q$de$q$,$q$full$q$,$q$622d354e2ac8be6daac51cbe0d520f67$q$,$q$Hol das Motorrad persönlich in Mezná bei Pelhřimov ab (von dort liefern wir es auch überallhin in Tschechien) oder selbst an der Selbstbedienungsfiliale in Velké Němčice bei Brno.$q$),
($q$20261112t06$q$,$q$cms_variables$q$,$q$web.home.process.steps.2.text$q$,$q$en$q$,$q$full$q$,$q$cbd77887593d998ec86768ea57c02034$q$,$q$Pick up the bike in person in Mezná near Pelhřimov (we can also deliver it anywhere in the Czech Republic from there), or collect it yourself at the self-service branch in Velké Němčice near Brno.$q$),
($q$20261112t06$q$,$q$cms_variables$q$,$q$web.home.process.steps.2.text$q$,$q$es$q$,$q$full$q$,$q$1debbdb722876b9350fb1e6e39c02e5d$q$,$q$Recoge la moto en persona en Mezná, cerca de Pelhřimov (desde allí también te la llevamos a cualquier lugar de la República Checa), o tú mismo en la sucursal de autoservicio de Velké Němčice, cerca de Brno.$q$),
($q$20261112t06$q$,$q$cms_variables$q$,$q$web.home.process.steps.2.text$q$,$q$fr$q$,$q$full$q$,$q$26f8396daf20758d121575fb98537ce9$q$,$q$Récupère la moto en personne à Mezná, près de Pelhřimov (d'où nous pouvons aussi la livrer partout en Tchéquie), ou toi-même à l'agence en libre-service de Velké Němčice, près de Brno.$q$),
($q$20261112t06$q$,$q$cms_variables$q$,$q$web.home.process.steps.2.text$q$,$q$nl$q$,$q$full$q$,$q$33e8f5dcaafa7e4c5879646ef4843d89$q$,$q$Haal de motor persoonlijk op in Mezná bij Pelhřimov (van daaruit bezorgen we hem ook overal in Tsjechië) of zelf bij de zelfbedieningsvestiging in Velké Němčice bij Brno.$q$),
($q$20261112t06$q$,$q$cms_variables$q$,$q$web.home.process.steps.2.text$q$,$q$pl$q$,$q$full$q$,$q$1215fe1f83900ffa32af157c9b2d378f$q$,$q$Odbierz motocykl osobiście w oddziale Mezná koło Pelhřimova (stamtąd dowieziemy go też w dowolne miejsce w Czechach) albo sam w samoobsługowym oddziale Velké Němčice koło Brna.$q$),
($q$20261112t06$q$,$q$cms_variables$q$,$q$web.home.process.steps.2.title$q$,$q$es$q$,$q$full$q$,$q$39a3946eee33eb73d04d997a1fffe2be$q$,$q$3. Recógela$q$),
($q$20261112t06$q$,$q$cms_variables$q$,$q$web.home.process.steps.2.title$q$,$q$fr$q$,$q$full$q$,$q$f440dd1b7cc2f232afc0b7d6e7429e35$q$,$q$3. Récupère$q$),
($q$20261112t06$q$,$q$cms_variables$q$,$q$web.home.signposts.3.text$q$,$q$cs$q$,$q$full$q$,$q$3be4b2abadfb1e122c2e8d634217fa59$q$,$q$Navštiv nás v Mezné u Pelhřimova nebo na samoobslužné pobočce ve Velkých Němčicích u Brna – případně nás kontaktuj.$q$),
($q$20261112t06$q$,$q$cms_variables$q$,$q$web.home.signposts.3.text$q$,$q$de$q$,$q$full$q$,$q$4a30c38cccdd1e7948c353065e72b400$q$,$q$Besuche uns in Mezná bei Pelhřimov oder an der Selbstbedienungsfiliale in Velké Němčice bei Brno – oder kontaktiere uns.$q$),
($q$20261112t06$q$,$q$cms_variables$q$,$q$web.home.signposts.3.text$q$,$q$en$q$,$q$full$q$,$q$dc0cfd8a6e8953f4a16f203600c41d1b$q$,$q$Visit us in Mezná near Pelhřimov or at the self-service branch in Velké Němčice near Brno – or get in touch.$q$),
($q$20261112t06$q$,$q$cms_variables$q$,$q$web.home.signposts.3.text$q$,$q$es$q$,$q$full$q$,$q$45becf857c7c41cddd878170c24067ec$q$,$q$Visítanos en Mezná, cerca de Pelhřimov, o en la sucursal de autoservicio de Velké Němčice, cerca de Brno – o ponte en contacto con nosotros.$q$),
($q$20261112t06$q$,$q$cms_variables$q$,$q$web.home.signposts.3.text$q$,$q$fr$q$,$q$full$q$,$q$b8f99ef3d6f8465b83e865b902912e9b$q$,$q$Rends-nous visite à Mezná, près de Pelhřimov, ou à l'agence en libre-service de Velké Němčice, près de Brno – ou contacte-nous.$q$),
($q$20261112t06$q$,$q$cms_variables$q$,$q$web.home.signposts.3.text$q$,$q$nl$q$,$q$full$q$,$q$0a3026e287f39b1600575a37550b9627$q$,$q$Bezoek ons in Mezná bij Pelhřimov of bij de zelfbedieningsvestiging in Velké Němčice bij Brno – of neem contact op.$q$),
($q$20261112t06$q$,$q$cms_variables$q$,$q$web.home.signposts.3.text$q$,$q$pl$q$,$q$full$q$,$q$35e71ecd0f433c5dc3837576e8e30e54$q$,$q$Odwiedź nas w oddziale Mezná koło Pelhřimova lub w samoobsługowym oddziale Velké Němčice koło Brna – albo skontaktuj się z nami.$q$),
($q$20261112t06$q$,$q$cms_variables$q$,$q$web.home.signposts.3.text$q$,$q$uk$q$,$q$full$q$,$q$3553761a68093a0836ac9bb6fcd0bd5c$q$,$q$Завітайте до нас у Mezná біля Пельгржимова або у філію самообслуговування Velké Němčice біля Брна – чи зв’яжіться з нами.$q$),
($q$20261112t06$q$,$q$cms_variables$q$,$q$web.pujcovna.faq.items.0.a$q$,$q$cs$q$,$q$full$q$,$q$a876898df6b7ff32129640ca74addcfc$q$,$q$Motorku si můžeš rezervovat přes náš online rezervační systém přímo tady na webu nebo v aplikaci MotoGo24, která je zdarma na Google Play (Android) i v App Store (iPhone). Případně se nám můžeš ozvat e-mailem, telefonicky nebo přes naše sociální sítě.$q$),
($q$20261112t06$q$,$q$cms_variables$q$,$q$web.pujcovna.faq.items.0.a$q$,$q$de$q$,$q$full$q$,$q$061c87fc7f3fd323ee0dddda612d57e5$q$,$q$Über unser Online-Buchungssystem direkt hier auf der Website oder in der MotoGo24-App, kostenlos bei Google Play (Android) und im App Store (iPhone). Oder melde dich per E-Mail, Telefon oder über unsere Social-Media-Kanäle.$q$),
($q$20261112t06$q$,$q$cms_variables$q$,$q$web.pujcovna.faq.items.0.a$q$,$q$en$q$,$q$full$q$,$q$19ff33e36a361858ca5c686165108efa$q$,$q$You can book a bike through our online booking system right here on the website or in the MotoGo24 app, free on Google Play (Android) and the App Store (iPhone). Or get in touch by e-mail, phone or through our social media.$q$),
($q$20261112t06$q$,$q$cms_variables$q$,$q$web.pujcovna.faq.items.0.a$q$,$q$es$q$,$q$full$q$,$q$63852021539cb7a4b120f843d3a469f2$q$,$q$Puedes reservar una moto con nuestro sistema de reserva online, aquí mismo en la web, o desde la app MotoGo24, gratis en Google Play (Android) y en el App Store (iPhone). Si lo prefieres, escríbenos por e-mail, llámanos o contáctanos por redes sociales.$q$),
($q$20261112t06$q$,$q$cms_variables$q$,$q$web.pujcovna.faq.items.0.a$q$,$q$fr$q$,$q$full$q$,$q$c6eaf73bfac71f78172d582e235acd34$q$,$q$Via notre système de réservation en ligne, directement ici sur le site, ou dans l'appli MotoGo24, gratuite sur Google Play (Android) et sur l'App Store (iPhone). Tu peux aussi nous contacter par e-mail, par téléphone ou sur nos réseaux sociaux.$q$),
($q$20261112t06$q$,$q$cms_variables$q$,$q$web.pujcovna.faq.items.0.a$q$,$q$nl$q$,$q$full$q$,$q$58fbce6c789be1220e1355973c8244ac$q$,$q$Je kunt een motor reserveren via ons online reserveringssysteem direct hier op de site of in de MotoGo24-app, gratis in Google Play (Android) en in de App Store (iPhone). Of neem contact op via e-mail, telefoon of social media.$q$),
($q$20261112t06$q$,$q$cms_variables$q$,$q$web.pujcovna.faq.items.0.a$q$,$q$pl$q$,$q$full$q$,$q$9d2eb37caa758d6454da76726c5fdaa5$q$,$q$Motocykl możesz zarezerwować przez nasz system rezerwacji online bezpośrednio na stronie albo w aplikacji MotoGo24 – za darmo w Google Play (Android) i w App Store (iPhone). Lub skontaktuj się z nami e-mailem, telefonicznie lub przez media społecznościowe.$q$),
($q$20261112t06$q$,$q$cms_variables$q$,$q$web.pujcovna.faq.items.0.a$q$,$q$uk$q$,$q$full$q$,$q$c8932bfab04be92e4a32973177dfb610$q$,$q$Мотоцикл можеш забронювати через нашу онлайн-систему бронювання прямо тут, на сайті, або в застосунку MotoGo24 – безкоштовно в Google Play (Android) і в App Store (iPhone). Або ж можеш зв’язатися з нами e-mailом, телефоном чи через наші соціальні мережі.$q$),
($q$20261112t07$q$,$q$faq_items$q$,$q$e6df7d9f-16a7-4ce6-8f9c-a046f40a1c63$q$,$q$en|answer$q$,$q$full$q$,$q$cf59f48a578a0708f83df2346a4d02cf$q$,$q$<p>We don't worry about the fuel level. You get the bike with whatever is in the tank at the time (it may not be full) and you refuel it yourself as needed during your ride. When you return it, you don't have to refuel – just make sure the reserve light isn't on. You don't pay anything extra for fuel.</p><p>You don't have to wash the bike at our staffed branch in Mezná. At the self-service branch in Velké Němčice, return it washed.</p>$q$),
($q$20261112t07$q$,$q$faq_items$q$,$q$e6df7d9f-16a7-4ce6-8f9c-a046f40a1c63$q$,$q$de|answer$q$,$q$full$q$,$q$bdeb0a0aea85ac8c1244e1f52fdbf136$q$,$q$<p>Um den Tankstand kümmern wir uns nicht. Du bekommst das Motorrad mit dem, was gerade im Tank ist (er muss nicht voll sein), und tankst unterwegs selbst nach Bedarf. Bei der Rückgabe musst du nicht tanken – nur die Reserveleuchte sollte nicht leuchten. Für Kraftstoff zahlst du nichts nach.</p><p>An unserer Filiale mit Personal in Mezná musst du das Motorrad nicht waschen. An der Selbstbedienungsfiliale in Velké Němčice bring es gewaschen zurück.</p>$q$),
($q$20261112t07$q$,$q$faq_items$q$,$q$e6df7d9f-16a7-4ce6-8f9c-a046f40a1c63$q$,$q$es|answer$q$,$q$full$q$,$q$e63e97965ebd9367dbe27b9150cb62a2$q$,$q$<p>No nos preocupamos por el nivel de combustible. Recibes la moto con el combustible que haya en ese momento en el depósito (puede que no esté lleno) y durante el viaje repostas tú mismo según lo necesites. Al devolverla no tienes que repostar; solo procura que no esté encendido el testigo de reserva. No pagas nada extra por el combustible.</p><p>En nuestra sucursal con personal de Mezná no tienes que lavar la moto. En la sucursal de autoservicio de Velké Němčice, devuélvela lavada.</p>$q$),
($q$20261112t07$q$,$q$faq_items$q$,$q$e6df7d9f-16a7-4ce6-8f9c-a046f40a1c63$q$,$q$fr|answer$q$,$q$full$q$,$q$a9df49c6b270c1dbb8fef706dbf1ebb4$q$,$q$<p>On ne se soucie pas du niveau de carburant. Tu reçois la moto avec ce qu'il y a dans le réservoir à ce moment-là (il n'est pas forcément plein) et tu fais le plein toi-même selon tes besoins pendant le trajet. Au retour, tu n'as pas besoin de faire le plein – veille seulement à ce que le voyant de réserve ne soit pas allumé. Tu ne paies rien en plus pour le carburant.</p><p>À notre agence avec personnel de Mezná, tu n'as pas besoin de laver la moto. À l'agence en libre-service de Velké Němčice, rends-la lavée.</p>$q$),
($q$20261112t07$q$,$q$faq_items$q$,$q$e6df7d9f-16a7-4ce6-8f9c-a046f40a1c63$q$,$q$nl|answer$q$,$q$full$q$,$q$46cf13df777bb6e539fc24c07e67aec1$q$,$q$<p>Het brandstofniveau maakt ons niet uit. Je krijgt de motor mee met wat er op dat moment in de tank zit (die hoeft niet vol te zijn) en onderweg tank je zelf wanneer nodig. Bij het terugbrengen hoef je niet te tanken – zorg alleen dat het reservelampje niet brandt. Voor brandstof betaal je niets bij.</p><p>Bij onze bemande vestiging in Mezná hoef je de motor niet te wassen. Bij de zelfbedieningsvestiging in Velké Němčice lever je hem gewassen in.</p>$q$),
($q$20261112t07$q$,$q$faq_items$q$,$q$e6df7d9f-16a7-4ce6-8f9c-a046f40a1c63$q$,$q$pl|answer$q$,$q$full$q$,$q$217360fc2cc55ed2d29c385a8122ef80$q$,$q$<p>Stanem paliwa się nie przejmujemy. Motocykl dostajesz z tym, co akurat jest w baku (nie musi być pełny), a w trasie tankujesz sam według potrzeb. Przy zwrocie nie musisz tankować – byle nie świeciła się kontrolka rezerwy. Za paliwo nic nie dopłacasz.</p><p>W oddziale z obsługą w Mezná nie musisz myć motocykla. W samoobsługowym oddziale Velké Němčice oddaj motocykl umyty.</p>$q$),
($q$20261112t07$q$,$q$faq_items$q$,$q$e6df7d9f-16a7-4ce6-8f9c-a046f40a1c63$q$,$q$uk|question$q$,$q$fill$q$,NULL,$q$Чи потрібно повертати мотоцикл із повним баком і чистим?$q$),
($q$20261112t07$q$,$q$faq_items$q$,$q$e6df7d9f-16a7-4ce6-8f9c-a046f40a1c63$q$,$q$uk|answer$q$,$q$fill$q$,NULL,$q$<p>Рівнем пального ми не переймаємося. Мотоцикл отримаєш із тим, що якраз є в баку (він може бути неповним), а під час поїздки заправляєшся сам за потреби. Під час повернення заправляти його не потрібно – лише стеж, щоб не світився індикатор резерву. За пальне нічого не доплачуєш.</p><p>У філії з персоналом у Mezná мотоцикл мити не потрібно. У філії самообслуговування Velké Němčice поверни його вимитим.</p>$q$),
($q$20261112t07$q$,$q$faq_items$q$,$q$02b6cfc8-83af-4887-8f5f-a62214f64f2a$q$,$q$uk|question$q$,$q$fill$q$,NULL,$q$Яке пальне мені заправляти?$q$),
($q$20261112t07$q$,$q$faq_items$q$,$q$02b6cfc8-83af-4887-8f5f-a62214f64f2a$q$,$q$uk|answer$q$,$q$fill$q$,NULL,$q$<p>Завжди пальне, <strong>передбачене виробником</strong> конкретного мотоцикла – знайдеш його в посібнику користувача, зазвичай і біля кришки бака (у наших мотоциклів це, як правило, бензин Natural 95). Якщо заправиш неправильне пальне, орендар у повному обсязі оплачує всі витрати на відкачування пального та ремонт двигуна. Під час повернення повний бак не потрібен, лише щоб не світився індикатор резерву.</p>$q$),
($q$20261112t07$q$,$q$faq_items$q$,$q$4975240d-08a4-458b-9a21-3ec8fb9557b1$q$,$q$pl|answer$q$,$q$phrase$q$,$q$1 kuferek lub zbiornik paliwa$q$,$q$1 kuferek lub torbę na bak$q$),
($q$20261112t07$q$,$q$faq_items$q$,$q$4975240d-08a4-458b-9a21-3ec8fb9557b1$q$,$q$pl|answer$q$,$q$phrase$q$,$q$stałą частью motocykla$q$,$q$stałą częścią motocykla$q$),
($q$20261112t07$q$,$q$faq_items$q$,$q$4975240d-08a4-458b-9a21-3ec8fb9557b1$q$,$q$fr|answer$q$,$q$phrase$q$,$q$en ont 1 ou un réservoir$q$,$q$en ont 1 ou une sacoche de réservoir$q$),
($q$20261112t07$q$,$q$faq_items$q$,$q$4975240d-08a4-458b-9a21-3ec8fb9557b1$q$,$q$es|answer$q$,$q$phrase$q$,$q$1 baúl o tankvak$q$,$q$1 baúl o una bolsa sobre el depósito$q$),
($q$20261112t07$q$,$q$faq_items$q$,$q$77557a0b-8c40-431e-a966-34848e738b7b$q$,$q$uk|answer$q$,$q$phrase$q$,$q$резервуар для палива$q$,$q$сумку на бак$q$),
($q$20261112t07$q$,$q$faq_items$q$,$q$77557a0b-8c40-431e-a966-34848e738b7b$q$,$q$fr|answer$q$,$q$phrase$q$,$q$un réservoir d'essence$q$,$q$une sacoche de réservoir$q$),
($q$20261112t08$q$,$q$faq_items$q$,$q$dac51062-20c0-4ea9-8422-54720f27b87e$q$,$q$cs|answer$q$,$q$full$q$,$q$99dbb53eee2c4c781e6c463f9fb2243f$q$,$q$Ano, vrácení na jiném místě je možné v rámci celé ČR. Cena se řídí stejným ceníkem jako přistavení – 500 Kč za nakládku/vykládku a 20 Kč/km od Mezné u Pelhřimova. Nebo můžeš motorku vrátit přímo u nás na pobočce. Vrácení jinde ale neplatí pro motorky ze samoobslužné pobočky ve Velkých Němčicích – ty se přebírají i vracejí jen přímo na této pobočce.&nbsp;$q$),
($q$20261112t08$q$,$q$faq_items$q$,$q$dac51062-20c0-4ea9-8422-54720f27b87e$q$,$q$de|answer$q$,$q$full$q$,$q$dc189c4fc5ee596e11ed96708ae34d5a$q$,$q$Ja, eine Rückgabe an einem anderen Ort ist in der gesamten ČR möglich. Der Preis richtet sich nach derselben Gebührentabelle wie die Anlieferung – 500 Kč für Be- und Entladung und 20 Kč/km von Mezná u Pelhřimova. Oder du kannst das Motorrad direkt bei uns in der Filiale zurückgeben. Die Rückgabe an einem anderen Ort gilt jedoch nicht für Motorräder der Selbstbedienungsfiliale in Velké Němčice – sie werden nur direkt in dieser Filiale übernommen und zurückgegeben.&nbsp;$q$),
($q$20261112t08$q$,$q$faq_items$q$,$q$dac51062-20c0-4ea9-8422-54720f27b87e$q$,$q$en|answer$q$,$q$full$q$,$q$908db04a76284c01339a68f29a815403$q$,$q$Yes, returning at a different location is possible throughout the Czech Republic. The price follows the same rate as delivery – 500 Kč for loading/unloading and 20 Kč/km from Mezná u Pelhřimova. Or you can return the motorcycle directly at our branch. Returning the bike elsewhere is not possible for bikes from the self-service branch in Velké Němčice – they are picked up and returned only at that branch.&nbsp;$q$),
($q$20261112t08$q$,$q$faq_items$q$,$q$dac51062-20c0-4ea9-8422-54720f27b87e$q$,$q$es|answer$q$,$q$full$q$,$q$36ea12b3cbbe1bcda7370b2361eef2d6$q$,$q$Sí, es posible devolver la motocicleta en otro lugar dentro de toda la República Checa. El precio se rige por la misma tarifa que el envío: 500 Kč por carga/descarga y 20 Kč/km desde Mezná u Pelhřimova. O puedes devolver la motocicleta directamente en nuestra sucursal. La devolución en otro lugar no es posible para las motos de la sucursal de autoservicio de Velké Němčice: se recogen y se devuelven solo en esa sucursal.&nbsp;$q$),
($q$20261112t08$q$,$q$faq_items$q$,$q$dac51062-20c0-4ea9-8422-54720f27b87e$q$,$q$fr|answer$q$,$q$full$q$,$q$7e42928ba061b960313361dcd6cd1b53$q$,$q$Oui, il est possible de retourner la moto à un autre endroit dans toute la République tchèque. Le prix est régi par le même barème que la livraison – 500 Kč pour le chargement/déchargement et 20 Kč/km à partir de Mezná u Pelhřimova. Ou tu peux retourner la moto directement à notre succursale. La restitution ailleurs ne s'applique pas aux motos de l'agence en libre-service de Velké Němčice : elles se retirent et se restituent uniquement dans cette agence.&nbsp;$q$),
($q$20261112t08$q$,$q$faq_items$q$,$q$dac51062-20c0-4ea9-8422-54720f27b87e$q$,$q$nl|answer$q$,$q$full$q$,$q$5a51c380af99fe9f5544eb3ce2a33526$q$,$q$Ja, het terugbrengen op een andere plaats is mogelijk in heel de ČR. De prijs volgt dezelfde prijslijst als levering – 500 Kč per laden/afladen en 20 Kč/km vanaf Mezná u Pelhřimova. Of je kunt de motor direct bij ons op de vestiging terugbrengen. Terugbrengen op een andere plek geldt niet voor motoren van de zelfbedieningsvestiging in Velké Němčice – die worden alleen bij die vestiging opgehaald en teruggebracht.&nbsp;$q$),
($q$20261112t08$q$,$q$faq_items$q$,$q$dac51062-20c0-4ea9-8422-54720f27b87e$q$,$q$pl|answer$q$,$q$full$q$,$q$fb0ed54a5be3ad6a800586dc43795d31$q$,$q$Tak, zwrot w innym miejscu jest możliwy na terenie całej ČR. Cena jest ustalana według tego samego cennika co dostawa – 500 Kč za załadunek/rozładunek i 20 Kč/km od Mezná u Pelhřimova. Możesz również zwrócić motocykl bezpośrednio w naszym oddziale. Zwrot w innym miejscu nie dotyczy jednak motocykli z samoobsługowego oddziału Velké Němčice – odbiera się je i zwraca wyłącznie w tym oddziale.&nbsp;$q$),
($q$20261112t08$q$,$q$faq_items$q$,$q$dac51062-20c0-4ea9-8422-54720f27b87e$q$,$q$uk|question$q$,$q$fill$q$,NULL,$q$Чи можу повернути мотоцикл в іншому місці, ніж його отримав?$q$),
($q$20261112t08$q$,$q$faq_items$q$,$q$dac51062-20c0-4ea9-8422-54720f27b87e$q$,$q$uk|answer$q$,$q$fill$q$,NULL,$q$Так, повернення в іншому місці можливе по всій Чехії. Ціна визначається за тим самим тарифом, що й доставка, – 500 Kč за завантаження/розвантаження та 20 Kč/км від Mezná біля Пельгржимова. Або можеш повернути мотоцикл безпосередньо в нашій філії. Проте повернення в іншому місці не стосується мотоциклів із філії самообслуговування Velké Němčice – їх отримують і повертають лише безпосередньо в цій філії.$q$),
($q$20261112t08$q$,$q$faq_items$q$,$q$19b96b98-8f06-485b-9748-b196de636132$q$,$q$cs|answer$q$,$q$full$q$,$q$a379e6f1819c82a03ac07532fd31943b$q$,$q$Ano, můžeš vyzvednout motorku u nás&nbsp; na pobočce a vrátit&nbsp; ji pak tam, kde ti to vyhovuje. Vrácení jinde ale neplatí pro motorky ze samoobslužné pobočky ve Velkých Němčicích – ty se přebírají i vracejí jen přímo na této pobočce.&nbsp;$q$),
($q$20261112t08$q$,$q$faq_items$q$,$q$19b96b98-8f06-485b-9748-b196de636132$q$,$q$de|answer$q$,$q$full$q$,$q$11d27b8bc7ee46c757e8c3a192c04403$q$,$q$Ja, du kannst das Motorrad bei uns&nbsp; in der Filiale abholen und es dann dort zurückgeben, wo es dir passt. Die Rückgabe an einem anderen Ort gilt jedoch nicht für Motorräder der Selbstbedienungsfiliale in Velké Němčice – sie werden nur direkt in dieser Filiale übernommen und zurückgegeben.&nbsp;$q$),
($q$20261112t08$q$,$q$faq_items$q$,$q$19b96b98-8f06-485b-9748-b196de636132$q$,$q$en|answer$q$,$q$full$q$,$q$36ea9fee2846df3a7847d45e5a205786$q$,$q$Yes, you can pick up a motorcycle at our branch and return it wherever works best for you. Returning the bike elsewhere is not possible for bikes from the self-service branch in Velké Němčice – they are picked up and returned only at that branch.&nbsp;$q$),
($q$20261112t08$q$,$q$faq_items$q$,$q$19b96b98-8f06-485b-9748-b196de636132$q$,$q$es|answer$q$,$q$full$q$,$q$e271466329132f3a03160773db760dca$q$,$q$Sí, puedes recoger la moto en nuestra&nbsp;sucursal y devolverla luego donde te convenga. La devolución en otro lugar no es posible para las motos de la sucursal de autoservicio de Velké Němčice: se recogen y se devuelven solo en esa sucursal.&nbsp;$q$),
($q$20261112t08$q$,$q$faq_items$q$,$q$19b96b98-8f06-485b-9748-b196de636132$q$,$q$fr|answer$q$,$q$full$q$,$q$2c875000860f344fa02f50e0f0680097$q$,$q$Oui, tu peux louer une moto à notre succursale et la retourner ensuite là où cela t'arrange. La restitution ailleurs ne s'applique pas aux motos de l'agence en libre-service de Velké Němčice : elles se retirent et se restituent uniquement dans cette agence.&nbsp;$q$),
($q$20261112t08$q$,$q$faq_items$q$,$q$19b96b98-8f06-485b-9748-b196de636132$q$,$q$nl|answer$q$,$q$full$q$,$q$c61eced735b0a48f82d62e5aaa2b6350$q$,$q$Ja, je kunt een motorfiets bij ons&nbsp;  op het kantoor ophalen en deze dan terugbrengen waar het jou uitkomt. Terugbrengen op een andere plek geldt niet voor motoren van de zelfbedieningsvestiging in Velké Němčice – die worden alleen bij die vestiging opgehaald en teruggebracht.&nbsp;$q$),
($q$20261112t08$q$,$q$faq_items$q$,$q$19b96b98-8f06-485b-9748-b196de636132$q$,$q$pl|answer$q$,$q$full$q$,$q$bf31964b83e4eecc43d1f28b456b2a3b$q$,$q$Tak, możesz odebrać motocykl w naszej&nbsp;  filii i zwrócić&nbsp;  go w wybranym przez siebie miejscu. Zwrot w innym miejscu nie dotyczy jednak motocykli z samoobsługowego oddziału Velké Němčice – odbiera się je i zwraca wyłącznie w tym oddziale.&nbsp;$q$),
($q$20261112t09$q$,$q$faq_items$q$,$q$19b96b98-8f06-485b-9748-b196de636132$q$,$q$uk|question$q$,$q$fill$q$,NULL,$q$Що, як я хочу забрати мотоцикл у прокаті, а повернути деінде – це можливо?$q$),
($q$20261112t09$q$,$q$faq_items$q$,$q$19b96b98-8f06-485b-9748-b196de636132$q$,$q$uk|answer$q$,$q$fill$q$,NULL,$q$Так, можеш забрати мотоцикл у нашій філії й повернути його там, де тобі зручно. Проте повернення в іншому місці не стосується мотоциклів із філії самообслуговування Velké Němčice – їх отримують і повертають лише безпосередньо в цій філії.$q$),
($q$20261112t09$q$,$q$faq_items$q$,$q$dd9c3286-142c-4601-9060-f7bb1f78f4a7$q$,$q$cs|answer$q$,$q$full$q$,$q$36488d57497d576c5294c75799d59768$q$,$q$Ano, přijedeme si pro motorku kamkoliv v České republice. Místo vrácení zadáš při rezervaci – může to být hotel, parkoviště, nádraží nebo jakákoliv jiná adresa. Vrácení jinde ale neplatí pro motorky ze samoobslužné pobočky ve Velkých Němčicích – ty se přebírají i vracejí jen přímo na této pobočce.$q$),
($q$20261112t09$q$,$q$faq_items$q$,$q$dd9c3286-142c-4601-9060-f7bb1f78f4a7$q$,$q$de|answer$q$,$q$full$q$,$q$854f263392ab002dc911a785d47a3221$q$,$q$Ja, wir holen das Motorrad überall in der Tschechischen Republik ab. Den Rückgabeort gibst du bei der Reservierung an – das kann ein Hotel, ein Parkplatz, ein Bahnhof oder eine beliebige andere Adresse sein. Die Rückgabe an einem anderen Ort gilt jedoch nicht für Motorräder der Selbstbedienungsfiliale in Velké Němčice – sie werden nur direkt in dieser Filiale übernommen und zurückgegeben.$q$),
($q$20261112t09$q$,$q$faq_items$q$,$q$dd9c3286-142c-4601-9060-f7bb1f78f4a7$q$,$q$en|answer$q$,$q$full$q$,$q$85bd05f02251e8b56dcc15e075a90938$q$,$q$Yes, we will pick up the motorcycle anywhere in the Czech Republic. You specify the return location during booking – it can be a hotel, parking lot, train station, or any other address. Returning the bike elsewhere is not possible for bikes from the self-service branch in Velké Němčice – they are picked up and returned only at that branch.$q$),
($q$20261112t09$q$,$q$faq_items$q$,$q$dd9c3286-142c-4601-9060-f7bb1f78f4a7$q$,$q$es|answer$q$,$q$full$q$,$q$fd4ef499d76fb7677b780dc227ff1c34$q$,$q$Sí, vendremos a recoger la moto a cualquier lugar de la República Checa. Especificas el lugar de devolución durante la reserva – puede ser un hotel, un aparcamiento, una estación de tren o cualquier otra dirección. La devolución en otro lugar no es posible para las motos de la sucursal de autoservicio de Velké Němčice: se recogen y se devuelven solo en esa sucursal.$q$),
($q$20261112t09$q$,$q$faq_items$q$,$q$dd9c3286-142c-4601-9060-f7bb1f78f4a7$q$,$q$fr|answer$q$,$q$full$q$,$q$39a54e3bb7f86409980580f437a92a64$q$,$q$Oui, nous venons chercher la moto partout en République tchèque. Vous indiquez le lieu de retour lors de la réservation – cela peut être un hôtel, un parking, une gare ou n'importe quelle autre adresse. La restitution ailleurs ne s'applique pas aux motos de l'agence en libre-service de Velké Němčice : elles se retirent et se restituent uniquement dans cette agence.$q$),
($q$20261112t09$q$,$q$faq_items$q$,$q$dd9c3286-142c-4601-9060-f7bb1f78f4a7$q$,$q$nl|answer$q$,$q$full$q$,$q$de55cb10439456fc782c197d6a5be0dc$q$,$q$Ja, we halen de motorfiets overal in de Tsjechische Republiek op. Je geeft de afleveringslocatie op bij de boeking – het kan een hotel, parkeerplaats, station of elk ander adres zijn. Terugbrengen op een andere plek geldt niet voor motoren van de zelfbedieningsvestiging in Velké Němčice – die worden alleen bij die vestiging opgehaald en teruggebracht.$q$),
($q$20261112t09$q$,$q$faq_items$q$,$q$dd9c3286-142c-4601-9060-f7bb1f78f4a7$q$,$q$pl|answer$q$,$q$full$q$,$q$ecf82d354e8677f71abd6e09e57ef6a0$q$,$q$Tak, przyjdziemy po motocykl gdziekolwiek w Republice Czeskiej. Miejsce zwrotu podajesz podczas rezerwacji – może to być hotel, parking, dworzec lub jakikolwiek inny adres. Zwrot w innym miejscu nie dotyczy jednak motocykli z samoobsługowego oddziału Velké Němčice – odbiera się je i zwraca wyłącznie w tym oddziale.$q$),
($q$20261112t09$q$,$q$faq_items$q$,$q$dd9c3286-142c-4601-9060-f7bb1f78f4a7$q$,$q$uk|question$q$,$q$fill$q$,NULL,$q$Чи можна повернути мотоцикл справді будь-де в Чехії?$q$),
($q$20261112t09$q$,$q$faq_items$q$,$q$dd9c3286-142c-4601-9060-f7bb1f78f4a7$q$,$q$uk|answer$q$,$q$fill$q$,NULL,$q$Так, ми приїдемо по мотоцикл будь-куди в Чеській Республіці. Місце повернення вкажеш під час бронювання – це може бути готель, парковка, вокзал чи будь-яка інша адреса. Проте повернення в іншому місці не стосується мотоциклів із філії самообслуговування Velké Němčice – їх отримують і повертають лише безпосередньо в цій філії.$q$),
($q$20261112t09$q$,$q$faq_items$q$,$q$5c385d19-7c6e-4f43-9645-bdc163424371$q$,$q$cs|answer$q$,$q$full$q$,$q$a9e7cfce4513f9ac56fc6718320ea8e2$q$,$q$Ano, při převzetí motorky je nutná osobní přítomnost – ověříme tvé doklady (ŘP a OP nebo PAS), předáme motorku a případnou výbavu a podepíšeme předávací protokol. Tak to probíhá na obslužné pobočce v Mezné. Na samoobslužné pobočce ve Velkých Němčicích si motorku převezmeš sám pomocí kódů z aplikace nebo e-mailu a předávací protokol podepíšeš na displeji – doklady musíš mít předem nahrané a ověřené online.$q$),
($q$20261112t09$q$,$q$faq_items$q$,$q$5c385d19-7c6e-4f43-9645-bdc163424371$q$,$q$de|answer$q$,$q$full$q$,$q$af966962782fac2ed7a6c1450565e14b$q$,$q$Ja, bei der Übernahme des Motorrads ist deine persönliche Anwesenheit erforderlich – wir überprüfen deine Dokumente (Führerschein und Personalausweis oder Reisepass), übergeben das Motorrad und eventuelle Ausrüstung und unterzeichnen das Übergabeprotokoll. So läuft es in unserer Filiale mit Personal in Mezná. An der Selbstbedienungsfiliale in Velké Němčice übernimmst du das Motorrad selbst mit den Codes aus der App oder E-Mail und unterschreibst das Übergabeprotokoll am Display – deine Dokumente müssen vorab online hochgeladen und geprüft sein.$q$),
($q$20261112t09$q$,$q$faq_items$q$,$q$5c385d19-7c6e-4f43-9645-bdc163424371$q$,$q$en|answer$q$,$q$full$q$,$q$49bc52764914a9b69c57071bb6cf7684$q$,$q$Yes, when picking up the motorcycle, your personal presence is required – we will verify your documents (driving licence and ID card or passport), hand over the motorcycle and any equipment, and sign a handover protocol. That is how it works at our staffed branch in Mezná. At the self-service branch in Velké Němčice you pick up the bike yourself with codes from the app or e-mail and sign the handover protocol on the display – your documents must be uploaded and verified online in advance.$q$),
($q$20261112t09$q$,$q$faq_items$q$,$q$5c385d19-7c6e-4f43-9645-bdc163424371$q$,$q$es|answer$q$,$q$full$q$,$q$f6f536261ee95a47c8657c3c1a918247$q$,$q$Sí, al recoger la moto es necesaria tu presencia personal – verificaremos tus documentos (licencia de conducir y documento de identidad o pasaporte), entregaremos la moto y el equipo correspondiente, y firmaremos el protocolo de entrega. Así funciona en nuestra sucursal con personal de Mezná. En la sucursal de autoservicio de Velké Němčice recoges la moto tú mismo con los códigos de la aplicación o del correo electrónico y firmas el protocolo de entrega en la pantalla; tus documentos deben estar subidos y verificados online con antelación.$q$),
($q$20261112t10$q$,$q$faq_items$q$,$q$5c385d19-7c6e-4f43-9645-bdc163424371$q$,$q$fr|answer$q$,$q$full$q$,$q$7ba7776ab89e8ae63ea7fa9766e282be$q$,$q$Oui, lors de la prise en charge de la moto, votre présence personnelle est obligatoire – nous vérifierons vos documents (permis de conduire et carte d'identité ou passeport), nous remettrons la moto et l'équipement éventuel et nous signerons le protocole de remise. C'est ainsi que cela se passe dans notre agence avec personnel de Mezná. À l'agence en libre-service de Velké Němčice, vous récupérez la moto vous-même avec les codes reçus dans l'application ou par e-mail et signez le protocole de remise sur l'écran – vos documents doivent être téléchargés et vérifiés en ligne au préalable.$q$),
($q$20261112t10$q$,$q$faq_items$q$,$q$5c385d19-7c6e-4f43-9645-bdc163424371$q$,$q$nl|answer$q$,$q$full$q$,$q$47e10930a78732dc0be1d9e89d5768d4$q$,$q$Ja, bij het ophalen van de motorfiets is persoonlijke aanwezigheid vereist – we verifiëren je documenten (rijbewijs en identiteitskaart of paspoort), we geven de motorfiets en eventuele uitrusting aan je over en we ondertekenen het overdrachtdocument. Zo gaat het bij onze bemande vestiging in Mezná. Bij de zelfbedieningsvestiging in Velké Němčice haal je de motor zelf op met de codes uit de app of e-mail en onderteken je het overdrachtsprotocol op het scherm – je documenten moeten vooraf online zijn geüpload en geverifieerd.$q$),
($q$20261112t10$q$,$q$faq_items$q$,$q$5c385d19-7c6e-4f43-9645-bdc163424371$q$,$q$pl|answer$q$,$q$full$q$,$q$6b2f0b30fee90c747e8b3c0578862b92$q$,$q$Tak, przy odbiorze motocykla wymagana jest osobista obecność – zweryfikujemy Twoje dokumenty (prawo jazdy i dowód osobisty lub paszport), wydamy motocykl i ewentualny sprzęt oraz podpiszemy protokół przekazania. Tak to wygląda w naszym oddziale z obsługą w Mezná. W samoobsługowym oddziale Velké Němčice odbierasz motocykl sam za pomocą kodów z aplikacji lub e-maila i podpisujesz protokół przekazania na wyświetlaczu – dokumenty musisz mieć wcześniej przesłane i zweryfikowane online.$q$),
($q$20261112t10$q$,$q$faq_items$q$,$q$5c385d19-7c6e-4f43-9645-bdc163424371$q$,$q$uk|question$q$,$q$fill$q$,NULL,$q$Чи потрібно приїжджати особисто?$q$),
($q$20261112t10$q$,$q$faq_items$q$,$q$5c385d19-7c6e-4f43-9645-bdc163424371$q$,$q$uk|answer$q$,$q$fill$q$,NULL,$q$Так, під час отримання мотоцикла потрібна твоя особиста присутність – перевіримо твої документи (посвідчення водія та ID-картку або паспорт), передамо мотоцикл і за потреби екіпірування та підпишемо протокол передачі. Так це відбувається у філії з персоналом у Mezná. У філії самообслуговування Velké Němčice мотоцикл забереш сам за допомогою кодів із застосунку або електронного листа, а протокол передачі підпишеш на дисплеї – документи мусиш заздалегідь завантажити онлайн, і їх мають перевірити.$q$),
($q$20261112t10$q$,$q$faq_items$q$,$q$333ae882-1e32-4d8e-818e-027e48af5c35$q$,$q$de|answer$q$,$q$phrase$q$,$q$(Kraftfahrzeugschein und Führerschein)$q$,$q$(Personalausweis und Führerschein)$q$),
($q$20261112t10$q$,$q$faq_items$q$,$q$333ae882-1e32-4d8e-818e-027e48af5c35$q$,$q$fr|answer$q$,$q$phrase$q$,$q$(carte grise et permis de conduire)$q$,$q$(carte d'identité et permis de conduire)$q$),
($q$20261112t10$q$,$q$faq_items$q$,$q$333ae882-1e32-4d8e-818e-027e48af5c35$q$,$q$pl|answer$q$,$q$phrase$q$,$q$(OP i ŘP)$q$,$q$(dowód osobisty i prawo jazdy)$q$),
($q$20261112t10$q$,$q$faq_items$q$,$q$0b7ecebd-da89-44ec-ab2b-e3ac2063781b$q$,$q$pl|answer$q$,$q$phrase$q$,$q$ważny dowód rejestracyjny lub paszport$q$,$q$ważny dowód osobisty lub paszport$q$),
($q$20261112t10$q$,$q$faq_items$q$,$q$0b7ecebd-da89-44ec-ab2b-e3ac2063781b$q$,$q$de|answer$q$,$q$phrase$q$,$q$einen gültigen OP oder PAS hat$q$,$q$einen gültigen Personalausweis oder Reisepass hat$q$),
($q$20261112t10$q$,$q$faq_items$q$,$q$e7079920-f08c-4b08-b52a-9b8623909035$q$,$q$uk|question$q$,$q$fill$q$,NULL,$q$Де відбувається отримання та повернення?$q$),
($q$20261112t10$q$,$q$faq_items$q$,$q$e7079920-f08c-4b08-b52a-9b8623909035$q$,$q$uk|answer$q$,$q$fill$q$,NULL,$q$У мотопрокаті за адресою Mezná 9, 393 01 Mezná (біля Пельгржимова). У формі бронювання можеш домовитися й про отримання чи повернення в іншому місці. Мотоцикли з філії самообслуговування Velké Němčice (Boudky, 691 63 Velké Němčice, біля Брна) отримують і повертають лише безпосередньо в цій філії, 24/7 за допомогою кодів із застосунку (бронювання зі знижкою за отримання з 12:00 кіоск видасть лише з 12:00) — доставку чи забирання для них не пропонуємо.$q$),
($q$20261112t11$q$,$q$faq_items$q$,$q$9eb4103e-9c51-4813-bc5e-73e5d2ba990d$q$,$q$cs|answer$q$,$q$phrase$q$,$q$nebo v naší aplikaci</span>.$q$,$q$nebo v naší aplikaci</span> (zdarma na Google Play pro Android i v App Store pro iPhone).$q$),
