CREATE TEMP TABLE t_cur AS
SELECT e.*, CASE e.tbl
  WHEN 'cms_variables' THEN (SELECT CASE WHEN e.sub='cs' THEN c.value #>> '{}' ELSE c.translations -> e.sub ->> 'value' END FROM public.cms_variables c WHERE c.key=e.k)
  WHEN 'app_settings' THEN (SELECT a.value #>> e.sub::text[] FROM public.app_settings a WHERE a.key=e.k)
  WHEN 'faq_items' THEN (SELECT CASE WHEN split_part(e.sub,'|',1)='cs' THEN (CASE WHEN split_part(e.sub,'|',2)='answer' THEN q.answer ELSE q.question END)
                         ELSE q.translations -> split_part(e.sub,'|',1) ->> split_part(e.sub,'|',2) END FROM public.faq_items q WHERE q.id=e.k::uuid)
  ELSE (SELECT CASE WHEN split_part(e.sub,'|',1)='cs' THEN (CASE WHEN split_part(e.sub,'|',2)='content' THEN p.content ELSE p.excerpt END)
                         ELSE p.translations -> split_part(e.sub,'|',1) ->> split_part(e.sub,'|',2) END FROM public.cms_pages p WHERE p.id=e.k::uuid)
  END AS cur
FROM t_exp e;
SELECT count(*) FILTER (WHERE cur IS NOT NULL AND (CASE how WHEN 'phrase' THEN strpos(cur,new)>0 ELSE cur=new END)) AS ok_new,
       count(*) FILTER (WHERE cur IS NOT NULL AND NOT (CASE how WHEN 'phrase' THEN strpos(cur,new)>0 ELSE cur=new END)
                         AND (CASE how WHEN 'full' THEN md5(cur)=old WHEN 'phrase' THEN strpos(cur,old)>0 ELSE coalesce(cur,'')='' END)) AS still_old,
       count(*) FILTER (WHERE cur IS NULL) AS missing,
       count(*) AS total
FROM t_cur;
SELECT 'STILL_OLD', f, tbl, k, sub FROM t_cur
 WHERE cur IS NOT NULL AND NOT (CASE how WHEN 'phrase' THEN strpos(cur,new)>0 ELSE cur=new END)
   AND (CASE how WHEN 'full' THEN md5(cur)=old WHEN 'phrase' THEN strpos(cur,old)>0 ELSE coalesce(cur,'')='' END);
SELECT 'OTHER', f, tbl, k, sub, left(cur,120) FROM t_cur
 WHERE cur IS NOT NULL AND NOT (CASE how WHEN 'phrase' THEN strpos(cur,new)>0 ELSE cur=new END)
   AND NOT (CASE how WHEN 'full' THEN md5(cur)=old WHEN 'phrase' THEN strpos(cur,old)>0 ELSE coalesce(cur,'')='' END);
